"""Independently verify visual coverage arithmetic and non-acceptance semantics."""

import json
from pathlib import Path

from matintegrity.models.inspection import VisualSurfaceExamination, visual_surface_summary

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "validation/visual_surface_math.json"
EVIDENCE = {
    "source_id": "authored-visual-validation",
    "origin": "synthetic",
    "citation": "independent synthetic verification generated by this project",
}


def main():
    request = VisualSurfaceExamination.model_validate(
        {
            "examination_id": "authored-visual-case",
            "procedure_id": "authored-procedure",
            "procedure_revision": "1",
            "examination_mode": "direct",
            "surface_condition": "authored clean surface condition",
            "surface_preparation": "authored preparation",
            "illumination_basis": "authored illumination basis",
            "resolution_check_basis": "authored resolution basis",
            "areas": [
                {
                    "area_id": "area-a",
                    "physical_location_id": "location-a",
                    "target_area_m2": 2.0,
                    "examined_area_m2": 1.5,
                    "unexamined_basis": "authored inaccessible segment",
                },
                {
                    "area_id": "area-b",
                    "physical_location_id": "location-b",
                    "target_area_m2": 1.0,
                    "examined_area_m2": 1.0,
                },
            ],
            "indications": [],
            "areas_mutually_exclusive_reviewed": True,
            "coverage_reviewed": True,
            "surface_condition_reviewed": True,
            "indication_mapping_reviewed": True,
            "negative_result_reviewed": True,
            "evidence": [EVIDENCE],
        }
    )
    result = visual_surface_summary(request)
    expected = 2.5 / 3.0
    absolute_error = abs(result.values["coverage_fraction"] - expected)
    forbidden = {"accepted", "acceptance", "probability_of_detection", "failure_probability"}
    forbidden_present = sorted(forbidden & set(result.values))
    if absolute_error > 1e-15 or result.status != "computed" or forbidden_present:
        raise ValueError("visual surface summary identity or semantics failed")
    report = {
        "schema": "matintegrity.visual_surface_math.v1",
        "expected_target_area_m2": 3.0,
        "computed_target_area_m2": result.values["target_area_m2"],
        "expected_examined_area_m2": 2.5,
        "computed_examined_area_m2": result.values["examined_area_m2"],
        "expected_coverage_fraction": expected,
        "computed_coverage_fraction": result.values["coverage_fraction"],
        "coverage_absolute_error": absolute_error,
        "forbidden_acceptance_or_probability_fields": forbidden_present,
        "qualification": (
            "Synthetic arithmetic and contract verification only; no visual procedure, inspector, "
            "surface, detection capability, indication classification or acceptance criterion is qualified."
        ),
    }
    OUTPUT.write_text(json.dumps(report, indent=2), encoding="utf-8")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
